// Practical recipes: explicit user decisions, real product boundaries, no unattended execution claims.
const recipe = (id, title, description, scenario, steps, review, limitation, related, appLink, image) => ({
  id: `workflow-${id}`, group: 'workflows', title, description,
  sections: [
    { id: 'scenario', title: 'When to use this workflow', paragraphs: [scenario] },
    { id: 'steps', title: 'Work through it', paragraphs: [], steps },
    { id: 'review', title: 'Check the result', paragraphs: [review] },
    { id: 'boundary', title: 'Keep the boundary clear', paragraphs: [limitation] },
  ], related, ...(appLink ? { appLink } : {}), ...(image ? { image } : {}),
});

